package app.unifeed.story;
import app.unifeed.cache.StoryIndex; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class StoryService {private final JdbcTemplate jdbc;private final StoryIndex index;public StoryService(JdbcTemplate jdbc,StoryIndex index){this.jdbc=jdbc;this.index=index;}
 @Transactional public UUID create(UUID user,String path){UUID id=UUID.randomUUID();Instant expiry=Instant.now().plus(24,java.time.temporal.ChronoUnit.HOURS);jdbc.update("INSERT INTO stories(id,author_id,media_path,expires_at) VALUES(?,?,?,?)",id,user,path,java.sql.Timestamp.from(expiry));index.add(id,expiry);return id;}
 public List<StoryDto> active(UUID viewer){return jdbc.query("SELECT s.id,s.author_id,u.display_name,u.avatar_path,s.media_path,s.expires_at,s.view_count,s.created_at FROM stories s JOIN users u ON u.id=s.author_id WHERE s.deleted_at IS NULL AND s.expires_at>now() AND u.deleted_at IS NULL AND (s.author_id=? OR EXISTS(SELECT 1 FROM follows f WHERE f.follower_id=? AND f.following_id=s.author_id)) ORDER BY s.created_at DESC",(rs,n)->new StoryDto((UUID)rs.getObject(1),(UUID)rs.getObject(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getTimestamp(6).toInstant(),rs.getInt(7),rs.getTimestamp(8).toInstant()),viewer,viewer);}
 @Transactional public void view(UUID story,UUID viewer){jdbc.update("UPDATE stories SET view_count=view_count+1 WHERE id=? AND author_id<>? AND deleted_at IS NULL AND expires_at>now()",story,viewer);}
 @Scheduled(fixedRate=60000) @Transactional public void expire(){Instant now=Instant.now();jdbc.update("UPDATE stories SET deleted_at=now() WHERE deleted_at IS NULL AND expires_at<=now()");index.removeExpired(now);}
 public record StoryDto(UUID id,UUID authorId,String authorName,String authorAvatarPath,String mediaPath,Instant expiresAt,int viewCount,Instant createdAt){} }
